CREATE OR REPLACE FUNCTION willflow_video_private.editor(p_ws uuid,p_user uuid) RETURNS boolean LANGUAGE sql STABLE SET search_path=public AS $$ SELECT p_user IS NOT NULL AND EXISTS(SELECT 1 FROM public.workspace_members WHERE workspace_id=p_ws AND user_id=p_user AND is_active) AND public.has_workspace_permission(p_user,p_ws,'projects.edit'); $$;
CREATE OR REPLACE FUNCTION willflow_video_private.active_subscription() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.workspace_is_active(NEW.workspace_id) OR NOT EXISTS(SELECT 1 FROM public.workspaces WHERE id=NEW.workspace_id AND subscription_plan='studio') THEN RAISE EXCEPTION 'Private Studio subscription required';END IF;RETURN NEW;END $$;
CREATE FUNCTION public.private_video_context(p_ws uuid,p_project uuid,p_task uuid,p_user uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM willflow_video_private.service_check(); IF NOT willflow_video_private.context_exists(p_ws,p_project,p_task) OR NOT EXISTS(SELECT 1 FROM public.workspace_members WHERE workspace_id=p_ws AND user_id=p_user AND is_active) THEN RAISE EXCEPTION 'Forbidden context';END IF; RETURN jsonb_build_object('enabled',EXISTS(SELECT 1 FROM willflow_video_private.enrollment WHERE workspace_id=p_ws AND enabled) AND public.workspace_is_active(p_ws) AND EXISTS(SELECT 1 FROM public.workspaces WHERE id=p_ws AND subscription_plan='studio'),'canEdit',willflow_video_private.editor(p_ws,p_user),'legacyBytes',(SELECT storage_used_bytes FROM public.workspace_storage WHERE workspace_id=p_ws),'privateBytes',coalesce((SELECT sum(bytes) FROM willflow_video_private.versions WHERE workspace_id=p_ws AND state NOT IN ('issued','aborted','withdrawn')),0),'limitBytes',(SELECT storage_limit_bytes FROM public.workspace_storage WHERE workspace_id=p_ws)); END $$;
CREATE FUNCTION public.private_video_client_list(p_ws uuid,p_project uuid,p_task uuid,p_user uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM willflow_video_private.service_check(); IF NOT EXISTS(SELECT 1 FROM public.workspace_members WHERE workspace_id=p_ws AND user_id=p_user AND is_active) OR (p_project IS NOT NULL AND NOT willflow_video_private.context_exists(p_ws,p_project,p_task)) THEN RAISE EXCEPTION 'Forbidden list';END IF; RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id',v.id,'file_name',v.file_name,'bytes',v.bytes,'created_at',v.created_at,'project_id',v.project_id,'task_id',v.task_id,'project_name',p.name,'canEdit',willflow_video_private.editor(p_ws,p_user),'state',v.state) ORDER BY v.created_at DESC) FROM willflow_video_private.versions v JOIN public.projects p ON p.id=v.project_id WHERE v.workspace_id=p_ws AND (p_project IS NULL OR (v.project_id=p_project AND v.task_id IS NOT DISTINCT FROM p_task)) AND willflow_video_private.permitted(v,p_user,NULL)),'[]'::jsonb); END $$;
CREATE FUNCTION public.private_video_client_feedback(p_request uuid,p_version uuid,p_user uuid,p_type text,p_body text,p_timestamp numeric) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v willflow_video_private.versions;display_name text;BEGIN PERFORM willflow_video_private.service_check();PERFORM pg_advisory_xact_lock(742019,1); SELECT * INTO v FROM willflow_video_private.versions WHERE id=p_version FOR UPDATE; IF NOT FOUND OR NOT willflow_video_private.permitted(v,p_user,NULL) OR p_type NOT IN ('comment','approval') OR (p_type='approval' AND NOT willflow_video_private.editor(v.workspace_id,p_user)) OR p_request IS NULL OR p_body IS NULL OR length(p_body)>5000 OR p_timestamp IS NULL OR p_timestamp<0 THEN RAISE EXCEPTION 'Forbidden feedback';END IF; SELECT coalesce(nullif(full_name,''),'Equipe') INTO display_name FROM public.profiles WHERE id=p_user;display_name:=left(coalesce(display_name,'Equipe'),120); IF p_type='comment' THEN IF length(btrim(p_body))=0 THEN RAISE EXCEPTION 'Empty comment';END IF; IF EXISTS(SELECT 1 FROM willflow_video_private.comments WHERE request_id=p_request AND ROW(version_id,digest,body,timestamp_seconds) IS DISTINCT FROM ROW(p_version,p_user::text,p_body,p_timestamp)) THEN RAISE EXCEPTION 'Feedback identity mismatch';END IF; INSERT INTO willflow_video_private.comments VALUES(gen_random_uuid(),p_request,p_version,p_user::text,display_name,p_body,p_timestamp,now()) ON CONFLICT(request_id) DO NOTHING; ELSE IF EXISTS(SELECT 1 FROM willflow_video_private.approvals WHERE request_id=p_request AND ROW(version_id,digest,notes) IS DISTINCT FROM ROW(p_version,p_user::text,p_body)) THEN RAISE EXCEPTION 'Feedback identity mismatch';END IF; INSERT INTO willflow_video_private.approvals VALUES(p_request,p_version,p_user::text,display_name,p_body,now()) ON CONFLICT(request_id) DO NOTHING; END IF;RETURN true; END $$;
CREATE FUNCTION public.private_video_client_withdraw(p_version uuid,p_user uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v willflow_video_private.versions;BEGIN PERFORM willflow_video_private.service_check();SELECT * INTO v FROM willflow_video_private.versions WHERE id=p_version; IF NOT FOUND OR NOT willflow_video_private.context_exists(v.workspace_id,v.project_id,v.task_id) OR NOT willflow_video_private.editor(v.workspace_id,p_user) THEN RAISE EXCEPTION 'Forbidden withdrawal';END IF; RETURN public.private_video_withdraw(v.operation_id,p_user,false); END $$;
CREATE FUNCTION public.private_video_revoke_scope(p_ws uuid,p_project uuid,p_task uuid,p_user uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM willflow_video_private.service_check();PERFORM pg_advisory_xact_lock(742019,1); IF NOT willflow_video_private.context_exists(p_ws,p_project,p_task) OR NOT willflow_video_private.editor(p_ws,p_user) THEN RAISE EXCEPTION 'Forbidden revocation';END IF; UPDATE willflow_video_private.links SET active=false WHERE workspace_id=p_ws AND project_id=p_project AND task_id IS NOT DISTINCT FROM p_task;RETURN true; END $$;
DO $$ DECLARE f record;BEGIN FOR f IN SELECT oid::regprocedure signature FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN ('private_video_context','private_video_client_list','private_video_client_feedback','private_video_client_withdraw','private_video_revoke_scope') LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated',f.signature);EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role',f.signature);END LOOP;END $$;